            }

            .document-outline__button {
                align-items: flex-start;
                background: none;
                border: none;
                border-radius: 2px;
                color: #1e1e1e;
                cursor: pointer;
                display: flex;
                margin: 0 0 0 -1px;
                padding: 2px 5px 2px 1px;
                text-align: left
            }

            .document-outline__button:disabled {
