            @media screen and (max-width: 782px) {
                #wp-admin-bar-root-default>#wp-admin-bar-duplicate-post,#wp-admin-bar-root-default>#wp-admin-bar-new-draft,#wp-admin-bar-root-default>#wp-admin-bar-rewrite-republish {
