            }

            .side_navigation.open {
                display: block;
                right: 0
            }

            .side_navigation .overlay {
                background-color: #000;
                opacity: 38%;
                width: 100%;
                height: 100%;
                position: absolute;
                top: 0;
                left: 0;
                z-index: 0
