            .side_navigation .navigation ul li.menu-item-has-children>a:after {
                content: '';
                position: absolute;
                width: 19px;
                height: 19px;
                background-image: url(//www.zillacapital.com/wp-content/themes/zilla-multiples/dist/css/../images/caret-up-colored.svg);
                background-repeat: no-repeat;
