                align-items: center;
                text-decoration: none;
                font-family: 'Rotunda-Regular';
                font-weight: 400;
                font-size: 14px;
                line-height: 1.36;
                letter-spacing: .21px;
                color: #fff;
                text-transform: capitalize
            }

            nav .navigation ul li a:after {
                position: absolute;
                content: '';
                bottom: 0;
                left: 0;
                height: 4px;
                width: 0;
                background-color: #4dc8ed;
