            nav .navigation ul li:hover a:after,nav .navigation ul li:focus a:after {
                width: 100%
            }

            nav .navigation ul li:hover .sub-menu,nav .navigation ul li:focus .sub-menu {
                display: block
            }

            nav .navigation ul li.current-menu-item a:after,nav .navigation ul li.current-menu-parent a:after {
