            .intl-tel-input {
                position: relative
            }

            .intl-tel-input * {
                box-sizing: border-box;
                -moz-box-sizing: border-box
            }

            .intl-tel-input .hide {
                display: none
            }

            .intl-tel-input .v-hide {
                visibility: hidden
            }

            .intl-tel-input input,.intl-tel-input input[type=text],.intl-tel-input input[type=tel] {
                position: relative;
                z-index: 0;
                margin-top: 0 !important;
                margin-bottom: 0 !important;
                padding-left: 48px !important;
                padding-right: 48px !important;
                margin-left: 0;
                transition: background-color .1s ease-out
            }

            .intl-tel-input input.iti-invalid-key {
                transition: background-color 0ms ease-out;
                background-color: #ffc7c7
            }

            .intl-tel-input .flag-container {
                position: absolute;
                top: 0;
                bottom: 0;
                padding: 1px
            }

            .intl-tel-input .flag-container:hover {
                cursor: pointer
            }

            .intl-tel-input .flag-container:hover .selected-flag {
                background-color: rgba(0,0,0,.05)
            }

            .intl-tel-input input[disabled]+.flag-container:hover,.intl-tel-input input[readonly]+.flag-container:hover {
                cursor: default
            }

            .intl-tel-input input[disabled]+.flag-container:hover .selected-flag,.intl-tel-input input[readonly]+.flag-container:hover .selected-flag {
                background-color: transparent
            }

            .intl-tel-input .selected-flag {
                z-index: 1;
                position: relative;
                width: 42px;
                height: 100%;
                padding: 0 15px 0 8px
            }

            .intl-tel-input .selected-flag .iti-flag {
                position: absolute;
                top: 0;
                bottom: 0;
                margin: auto
            }

            .intl-tel-input .selected-flag .iti-arrow {
                position: absolute;
                top: 50%;
                margin-top: -2px;
                right: 4px;
                width: 0;
                height: 0;
                border-left: 3px solid transparent;
                border-right: 3px solid transparent;
                border-top: 4px solid #555
            }

            .intl-tel-input .selected-flag .iti-arrow.up {
                border-top: none;
                border-bottom: 4px solid #555
            }

            .intl-tel-input .country-list {
                list-style: none !important;
                position: absolute;
                z-index: 2;
                padding: 0 !important;
                margin: 0 0 0 -1px;
                box-shadow: 1px 1px 4px rgba(0,0,0,.2);
                background-color: #fff;
                border: 1px solid #ccc;
                white-space: nowrap;
                max-height: 200px;
                overflow-y: scroll
            }

            .intl-tel-input .country-list.dropup {
                bottom: 100%;
                margin-bottom: -1px
            }

            .intl-tel-input .country-list .flag-box {
                display: inline-block;
                width: 20px
            }

            @media (max-width: 500px) {
                .intl-tel-input .country-list {
                    white-space:normal
                }
            }

            .intl-tel-input .country-list .divider {
                padding-bottom: 5px;
                margin-bottom: 5px;
                border-bottom: 1px solid #ccc
            }

            .intl-tel-input .country-list .country {
                padding: 5px 10px;
                margin-left: 0
            }

            .intl-tel-input .country-list .country .dial-code {
                color: #999
            }

            .intl-tel-input .country-list .country.highlight {
                background-color: rgba(0,0,0,.05)
            }

            .intl-tel-input .country-list .flag-box,.intl-tel-input .country-list .country-name,.intl-tel-input .country-list .dial-code {
                vertical-align: middle
            }

            .intl-tel-input .country-list .flag-box,.intl-tel-input .country-list .country-name {
                margin-right: 6px;
                margin-left: 6px
            }

            .intl-tel-input select {
                position: absolute;
                top: 0;
                left: 0;
                z-index: 1;
                width: 42px;
                height: 100%;
                opacity: 0
            }

            .intl-tel-input.iti-container {
                position: absolute;
                top: -1000px;
                left: -1000px;
                z-index: 1060;
                padding: 1px
            }

            .intl-tel-input.iti-container:hover {
                cursor: pointer
            }

